        }
        function Invoke-ReplPersistTurn {
            param(
                [Parameter(Mandatory)][string]$RequestId,
                [AllowEmptyString()][string]$Title = '',
                [string]$Status = '',
                [string]$ResponseText = '',
                [switch]$IncludeSessionTitle,
                [string]$PlanFile,
                [string]$TodoId
            )
            if ($null -eq $script:PersistCallCount) { $script:PersistCallCount = 0 }
