$nativeNames=@($nunit.SelectNodes('//test-case') | ForEach-Object {$_.name})
$rows=@($m.requirementAcceptanceCoverage | Where-Object requirementId -Match '^(FR|TR|TEST)-MCP-SESSIONLIFE-00[123]$')
foreach($r in $rows){
